import React, { useState, useMemo } from 'react';
import { Button, Form } from 'react-bootstrap';
import PatientTable from '../components/PatientTable';
import PatientModal from '../components/PatientModal';

const Dashboard = () => {
  const [patients, setPatients] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [activeFilter, setActiveFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  const handleOpenModal = (patient = null) => {
    setSelectedPatient(patient);
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setSelectedPatient(null);
  };

  const handleSavePatient = (patientData) => {
    if (selectedPatient) {
      // Edit mode
      setPatients(patients.map(p => p.id === selectedPatient.id ? { ...p, ...patientData } : p));
    } else {
      // Add mode
      const newPatient = {
        ...patientData,
        id: Date.now().toString(),
        createdAt: new Date().toISOString(),
        remarks: 'Processing by AI...' 
      };
      setPatients([...patients, newPatient]);
    }
    handleCloseModal();
  };

  const handleDeletePatient = (patientId) => {
    setPatients(patients.filter(p => p.id !== patientId));
  };

  // Helper functions for categorization
  const isAtRisk = (remarks) => {
    if (!remarks) return false;
    const lower = remarks.toLowerCase();
    return ['risk', 'high', 'elevated', 'danger'].some(word => lower.includes(word));
  };

  const needsMonitoring = (remarks) => {
    if (!remarks) return false;
    const lower = remarks.toLowerCase();
    return ['moderate', 'borderline', 'monitor'].some(word => lower.includes(word));
  };

  const isThisWeek = (dateString) => {
    if (!dateString) return false;
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    return diffDays <= 7;
  };

  // Stats for cards
  const stats = useMemo(() => {
    return {
      total: patients.length,
      atRisk: patients.filter(p => isAtRisk(p.remarks)).length,
      monitoring: patients.filter(p => needsMonitoring(p.remarks)).length,
      thisWeek: patients.filter(p => isThisWeek(p.createdAt)).length
    };
  }, [patients]);

  // Filtered and searched patients
  const displayPatients = useMemo(() => {
    let filtered = patients;

    // Apply Card Filter
    if (activeFilter === 'At Risk') {
      filtered = filtered.filter(p => isAtRisk(p.remarks));
    } else if (activeFilter === 'Needs Monitoring') {
      filtered = filtered.filter(p => needsMonitoring(p.remarks));
    } else if (activeFilter === 'This Week') {
      filtered = filtered.filter(p => isThisWeek(p.createdAt));
    }

    // Apply Search Query
    if (searchQuery.trim() !== '') {
      const q = searchQuery.toLowerCase();
      filtered = filtered.filter(p => 
        (p.fullName && p.fullName.toLowerCase().includes(q)) || 
        (p.email && p.email.toLowerCase().includes(q))
      );
    }

    return filtered;
  }, [patients, activeFilter, searchQuery]);

  return (
    <div className="max-w-7xl mx-auto p-5">
      <div className="mb-5">
        <h2 className="text-2xl font-bold text-gray-800">Patient Dashboard</h2>
        <p className="text-gray-500 text-sm mt-1">Manage and view patient medical records</p>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-5">
        <div 
          onClick={() => setActiveFilter('All')}
          className={`relative bg-white rounded-lg shadow-sm border-l-4 border-blue-500 p-3 cursor-pointer transition-colors ${activeFilter === 'All' ? 'bg-blue-50/50' : 'hover:bg-gray-50'}`}
        >
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Total Patients</p>
          <p className="text-[2rem] font-bold text-gray-800 leading-none mt-2">{stats.total}</p>
          <div className="absolute top-3 right-3 text-lg opacity-80">🧑‍⚕️</div>
        </div>

        <div 
          onClick={() => setActiveFilter('At Risk')}
          className={`relative bg-white rounded-lg shadow-sm border-l-4 border-red-500 p-3 cursor-pointer transition-colors ${activeFilter === 'At Risk' ? 'bg-red-50/50' : 'hover:bg-gray-50'}`}
        >
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">At Risk</p>
          <p className="text-[2rem] font-bold text-gray-800 leading-none mt-2">{stats.atRisk}</p>
          <div className="absolute top-3 right-3 text-lg opacity-80">🚨</div>
        </div>

        <div 
          onClick={() => setActiveFilter('Needs Monitoring')}
          className={`relative bg-white rounded-lg shadow-sm border-l-4 border-yellow-500 p-3 cursor-pointer transition-colors ${activeFilter === 'Needs Monitoring' ? 'bg-yellow-50/50' : 'hover:bg-gray-50'}`}
        >
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Needs Monitoring</p>
          <p className="text-[2rem] font-bold text-gray-800 leading-none mt-2">{stats.monitoring}</p>
          <div className="absolute top-3 right-3 text-lg opacity-80">⚠️</div>
        </div>

        <div 
          onClick={() => setActiveFilter('This Week')}
          className={`relative bg-white rounded-lg shadow-sm border-l-4 border-green-500 p-3 cursor-pointer transition-colors ${activeFilter === 'This Week' ? 'bg-green-50/50' : 'hover:bg-gray-50'}`}
        >
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Added This Week</p>
          <p className="text-[2rem] font-bold text-gray-800 leading-none mt-2">{stats.thisWeek}</p>
          <div className="absolute top-3 right-3 text-lg opacity-80">📅</div>
        </div>
      </div>

      {/* Controls */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-4 w-1/3">
          <Form.Control
            type="text"
            placeholder="Search by name or email..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="rounded-lg shadow-sm border-gray-200 text-sm py-1.5"
          />
          {activeFilter !== 'All' && (
            <button 
              onClick={() => setActiveFilter('All')} 
              className="text-sm text-blue-600 hover:text-blue-800 whitespace-nowrap"
            >
              Clear Filter
            </button>
          )}
        </div>
        <Button 
          variant="primary" 
          className="bg-blue-600 hover:bg-blue-700 border-0 font-medium shadow-sm rounded-lg px-4 py-2 text-sm"
          onClick={() => handleOpenModal()}
        >
          + Add Patient
        </Button>
      </div>

      <PatientTable 
        patients={displayPatients} 
        activeFilter={activeFilter}
        onEdit={handleOpenModal} 
        onDelete={handleDeletePatient} 
      />

      <PatientModal 
        show={showModal} 
        onHide={handleCloseModal} 
        onSave={handleSavePatient}
        patientData={selectedPatient}
      />
    </div>
  );
};

export default Dashboard;
